import{_ as a,c as i,o as t,ag as r}from"./chunks/framework.ARG558ZT.js";const h=JSON.parse('{"title":"A09 — SQS orders, DynamoDB streams and SNS","description":"","frontmatter":{},"headers":[],"relativePath":"practice/aws/associate-09.md","filePath":"practice/aws/associate-09.md"}'),o={name:"practice/aws/associate-09.md"};function n(s,e,d,l,c,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="a09-—-sqs-orders-dynamodb-streams-and-sns" tabindex="-1">A09 — SQS orders, DynamoDB streams and SNS <a class="header-anchor" href="#a09-—-sqs-orders-dynamodb-streams-and-sns" aria-label="Permalink to “A09 — SQS orders, DynamoDB streams and SNS”">​</a></h1><p><strong>Learner status: not started. All supplied tasks on this page are mandatory in this learning path</strong>, including items originally labelled optional or bonus. Repeating tasks still require the stated action or comparison; reuse earlier resources and code where suitable, and record the new evidence. Source optional labels describe the original course only.</p><p><strong>Read first:</strong> <a href="./../../aws/messaging.html">messaging</a>.</p><p>Use the client/backend <code>feat/sns-sqs-lab</code> branches and supplied handler samples. This lab repeats P06&#39;s queue/notification concepts but adds a DynamoDB-stream transition.</p><h2 id="a09-1-—-queue-to-notification-path-—-repeating-p06" tabindex="-1">A09.1 — Queue-to-notification path — repeating P06 <a class="header-anchor" href="#a09-1-—-queue-to-notification-path-—-repeating-p06" aria-label="Permalink to “A09.1 — Queue-to-notification path — repeating P06”">​</a></h2><ul><li>[ ] Create Standard <code>OrdersQueue</code>, SNS <code>OrderPlaced</code> and confirmed email subscriptions plus a permitted phone-number subscription. Send sample notifications and verify delivery using only destinations you control.</li><li>[ ] Create <code>OrderNotifier</code> with queue consumption and SNS publishing permissions; configure the actual topic ARN.</li><li>[ ] Connect SQS with batch size 10/window 5 seconds, or document the source-permitted chosen values.</li><li>[ ] Run both apps locally, configure <code>sqs.ordersQueueUrl</code> and the intended profile, place an order from the cart and verify notification delivery.</li></ul><h2 id="a09-2-—-persist-before-notification" tabindex="-1">A09.2 — Persist before notification <a class="header-anchor" href="#a09-2-—-persist-before-notification" aria-label="Permalink to “A09.2 — Persist before notification”">​</a></h2><ul><li>[ ] Remove the original notifier&#39;s SQS trigger; create DynamoDB <code>Orders</code>.</li><li>[ ] Create <code>OrderWriter</code> with queue and table permissions and an SQS mapping. Submit an order and inspect persisted items.</li><li>[ ] Enable the table&#39;s <code>NEW_IMAGE</code> stream, attach <code>OrderNotifier</code> with batch size 5, adapt it to stream records and grant stream-reading permissions.</li><li>[ ] Place another order and verify notification follows database persistence. Avoid leaving competing SQS consumers from the prior topology active unintentionally.</li></ul><h2 id="a09-3-—-dead-letter-path-—-repeating-p06-with-controlled-failure" tabindex="-1">A09.3 — Dead-letter path — repeating P06 with controlled failure <a class="header-anchor" href="#a09-3-—-dead-letter-path-—-repeating-p06-with-controlled-failure" aria-label="Permalink to “A09.3 — Dead-letter path — repeating P06 with controlled failure”">​</a></h2><ul><li>[ ] Create <code>OrdersDLQ</code>, connect it through <code>OrdersQueue</code>&#39;s redrive policy and demonstrate the source&#39;s maximum-receive value of 1 as a deliberately sensitive lab setting.</li><li>[ ] Create <code>UnprocessedOrderNotifier</code>, configure its topic and queue permissions and attach the DLQ mapping.</li><li>[ ] Deliberately produce an isolated processing failure to demonstrate DLQ delivery, and compare with a successfully processed order. A normal successful order need not enter the DLQ; do not rely on random retries to demonstrate it.</li><li>[ ] Raise the threshold and explain retry tolerance. Clean the synthetic failure and record any side effects before replay/removal.</li></ul><h2 id="a09-4-—-deploy-and-filter-—-promoted-from-optional-repeating-p06" tabindex="-1">A09.4 — Deploy and filter — promoted from optional; repeating P06 <a class="header-anchor" href="#a09-4-—-deploy-and-filter-—-promoted-from-optional-repeating-p06" aria-label="Permalink to “A09.4 — Deploy and filter — promoted from optional; repeating P06”">​</a></h2><ul><li>[ ] Deploy the apps and verify the complete cloud-hosted order flow.</li><li>[ ] Add message attributes such as high/low price classifications; configure email/SMS subscription filtering and demonstrate matching and non-matching messages.</li><li>[ ] Remove unused queues, topics, subscriptions, functions, tables and instances after evidence collection. Check notification and SMS costs for the actual destination/service configuration.</li></ul><h2 id="completion-evidence" tabindex="-1">Completion evidence <a class="header-anchor" href="#completion-evidence" aria-label="Permalink to “Completion evidence”">​</a></h2><ul><li>[ ] Record observed results for every section, including all promoted extensions.</li><li>[ ] Retain configuration/code, successful and denied/failing cases where specified, and actual cleanup state.</li><li>[ ] Link earlier evidence for repeating work and add the new interface/behavior comparison.</li></ul><p>Use the <a href="./#evidence-for-every-required-module">shared evidence rules</a>; never claim screenshots or sample code complete independent work.</p>',15)])])}const m=a(o,[["render",n]]);export{h as __pageData,m as default};
